<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Workspace;
use App\Services\Identity;
use App\Services\SafeMonitor;
use App\Services\TechnologyAccess as T;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
use Tests\TestCase;
class TechnologyTest extends TestCase {
 use RefreshDatabase;
 private function team():array{$o=User::factory()->create();$a=User::factory()->create();$m=User::factory()->create();$e=User::factory()->create();$w=Workspace::create(['name'=>'Example','type'=>'business','owner_id'=>$o->id]);$w->members()->attach([$o->id=>['role'=>'owner'],$a->id=>['role'=>'admin'],$m->id=>['role'=>'manager'],$e->id=>['role'=>'member']]);return [$w,$o,$a,$m,$e];}
 private function login(User $u,Workspace $w):static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version,'workspace_id'=>$w->id])->withoutVite();}
 private function asset(string $kind,string $name,string $status,array $extra=[]):int{$this->post('/technology',array_merge(compact('kind','name','status'),$extra))->assertRedirect('/technology');return DB::table('tech_assets')->latest('id')->value('id');}
 private function domain():int{return $this->asset('domain','Public domain','active',['details'=>['hostname'=>'www.example.com']]);}
 private function monitor(int $id):int{$this->post('/technology/monitors',['asset_id'=>$id,'interval_minutes'=>15,'authorized'=>1])->assertRedirect();return DB::table('tech_monitors')->latest('id')->value('id');}
 private function fakeProbe():SafeMonitor{return new class extends SafeMonitor {public int $calls=0;public function probe(string $host):array{$this->calls++;return ['status'=>'up','http_status'=>200,'latency_ms'=>42];}};}
 public function test_guest_personal_manager_member_denied():void{$this->get('/technology')->assertRedirect('/login');[$w,$o,$a,$m,$e]=$this->team();$this->login($o,Identity::personal($o))->get('/technology')->assertForbidden();$this->login($m,$w)->get('/technology')->assertForbidden();$this->login($e,$w)->post('/technology',['kind'=>'server','name'=>'Denied','status'=>'active'])->assertForbidden();$this->get('/dashboard')->assertOk()->assertDontSee('Infrastructure overview');$this->login($a,$w)->get('/technology')->assertOk();}
 public function test_software_inventory_parent_types_and_stale_version():void{[$w,$o]=$this->team();$this->login($o,$w);$p=$this->asset('product','App','active');$r=$this->asset('repository','Source','active',['parent_id'=>$p,'details'=>['url'=>'https://github.com/example/repo','branch'=>'main']]);$rel=$this->asset('release','Version one','released',['parent_id'=>$r,'details'=>['version'=>'1.0']]);$this->asset('deployment','Production','successful',['parent_id'=>$rel]);$this->asset('issue','Bug','open',['parent_id'=>$r,'details'=>['severity'=>'high']]);$this->post('/technology',['kind'=>'ssl','name'=>'Wrong parent','status'=>'active','parent_id'=>$p])->assertSessionHasErrors('parent_id');$this->put('/technology/'.$r,['name'=>'Source updated','status'=>'active','parent_id'=>$p,'version'=>1])->assertRedirect('/technology');$this->put('/technology/'.$r,['name'=>'Stale','status'=>'active','parent_id'=>$p,'version'=>1])->assertSessionHasErrors('version');$this->get('/technology?kind=repository')->assertOk()->assertSee('Source updated');$this->get('/technology/'.$r.'/edit')->assertOk();}
 public function test_server_metrics_and_backup_checklist():void{[$w,$o]=$this->team();$this->login($o,$w);$s=$this->asset('server','VPS','active',['details'=>['server_type'=>'vps','cpu_cores'=>4,'ram_gb'=>8]]);$this->post('/technology/metrics',['asset_id'=>$s,'cpu'=>101,'memory'=>50,'disk'=>40])->assertSessionHasErrors('cpu');$this->post('/technology/metrics',['asset_id'=>$s,'cpu'=>25,'memory'=>50,'disk'=>40])->assertRedirect();$this->asset('backup','Daily backup','restore_verified',['parent_id'=>$s]);$this->post('/technology/checklists',['asset_id'=>$s,'kind'=>'security','title'=>'Patch OS'])->assertRedirect();$id=DB::table('tech_checklists')->value('id');$this->patch('/technology/checklists/'.$id,['completed'=>1])->assertRedirect();$this->assertNotNull(DB::table('tech_checklists')->value('completed_at'));$this->patch('/technology/checklists/'.$id,['completed'=>0])->assertRedirect();$this->assertNull(DB::table('tech_checklists')->value('completed_at'));$this->get('/technology')->assertOk()->assertSee('Manual sample')->assertSee('Patch OS');}
 public function test_domain_ssl_renewal_incident_and_dashboard():void{[$w,$o]=$this->team();$this->login($o,$w);$d=$this->domain();$this->asset('ssl','TLS cert','active',['parent_id'=>$d,'due_date'=>now()->addDays(10)->toDateString()]);$this->asset('renewal','Domain renewal','pending',['parent_id'=>$d,'due_date'=>now()->addDays(15)->toDateString()]);$this->asset('incident','Outage','open',['parent_id'=>$d,'details'=>['severity'=>'critical']]);$stats=T::stats($w,$o);$this->assertSame(2,$stats['renewals']);$this->assertSame(1,$stats['incidents']);$this->get('/dashboard')->assertOk()->assertSee('Infrastructure overview');}
 public function test_cross_workspace_relations_and_edits_denied():void{[$w,$o]=$this->team();$this->login($o,$w);$d=$this->domain();$s=$this->asset('server','Private VPS','active');$m=$this->monitor($d);[$other,$owner]=$this->team();$this->login($owner,$other);$this->get('/technology')->assertOk()->assertDontSee('Private VPS')->assertDontSee('www.example.com');$this->get('/technology/'.$s.'/edit')->assertNotFound();$this->put('/technology/'.$s,['name'=>'Foreign','status'=>'active','version'=>1])->assertNotFound();$this->post('/technology',['kind'=>'ssl','name'=>'Foreign','status'=>'active','parent_id'=>$d])->assertNotFound();$this->post('/technology/metrics',['asset_id'=>$s,'cpu'=>1,'memory'=>1,'disk'=>1])->assertNotFound();$this->patch('/technology/monitors/'.$m,['enabled'=>0])->assertNotFound();}
 public function test_ssrf_hostname_and_ip_validation():void{foreach(['localhost','127.0.0.1','https://example.com','example.com:443','a.local','a.internal','a.example','a.com/path','user@a.com','[::1]','a.com?x=1'] as $host){try{SafeMonitor::hostname($host);$this->fail('Accepted '.$host);}catch(ValidationException){$this->assertTrue(true);}}foreach(['127.0.0.1','0.0.0.0','10.0.0.1','172.16.0.1','192.168.1.1','169.254.169.254','100.64.0.1','198.18.0.1','192.0.2.1','224.0.0.1','240.0.0.1','255.255.255.255','::1','::ffff:127.0.0.1'] as $ip)$this->assertFalse(SafeMonitor::publicIp($ip),$ip);$this->assertTrue(SafeMonitor::publicIp('8.8.8.8'));$this->assertSame('www.example.com',SafeMonitor::hostname('WWW.Example.COM'));}
 public function test_ssrf_mixed_dns_and_pinned_connection():void{$probe=new class extends SafeMonitor {public array $ips=[];public array $requests=[];public function resolve(string $host):array{return $this->ips;}protected function request(string $host,string $ip):array{$this->requests[]=[$host,$ip];return ['status'=>'up','http_status'=>200,'latency_ms'=>10];}};$probe->ips=['8.8.8.8','127.0.0.1'];$this->assertSame('blocked',$probe->probe('www.example.com')['status']);$this->assertCount(0,$probe->requests);$probe->ips=[];$this->assertSame('blocked',$probe->probe('www.example.com')['status']);$probe->ips=['8.8.8.8'];$this->assertSame('up',$probe->probe('www.example.com')['status']);$this->assertSame([['www.example.com','8.8.8.8']],$probe->requests);}
 public function test_monitor_operator_opt_in_and_idempotent_tick():void{[$w,$o]=$this->team();$this->login($o,$w);$d=$this->domain();$m=$this->monitor($d);config(['technology.monitoring_enabled'=>false]);$this->patch('/technology/monitors/'.$m,['enabled'=>1])->assertStatus(409);$fake=$this->fakeProbe();$this->app->instance(SafeMonitor::class,$fake);$this->artisan('technology:tick')->assertExitCode(0);$this->assertSame(0,$fake->calls);config(['technology.monitoring_enabled'=>true]);$this->patch('/technology/monitors/'.$m,['enabled'=>1])->assertRedirect();$this->artisan('technology:tick')->assertExitCode(0);$this->artisan('technology:tick')->assertExitCode(0);$this->assertSame(1,$fake->calls);$this->assertDatabaseHas('tech_monitor_samples',['monitor_id'=>$m,'status'=>'up','latency_ms'=>42]);$this->get('/technology')->assertOk()->assertSee('100.00%');}
 public function test_monitor_revocation_and_domain_lifecycle():void{[$w,$o,$a]=$this->team();$this->login($a,$w);$d=$this->domain();$m=$this->monitor($d);config(['technology.monitoring_enabled'=>true]);$this->patch('/technology/monitors/'.$m,['enabled'=>1])->assertRedirect();$this->login($o,$w)->patch('/workspaces/'.$w->id.'/members/'.$a->id,['role'=>'member'])->assertRedirect();$fake=$this->fakeProbe();$this->app->instance(SafeMonitor::class,$fake);$this->artisan('technology:tick')->assertExitCode(0);$this->assertSame(0,$fake->calls);$this->assertDatabaseHas('tech_monitors',['id'=>$m,'enabled'=>0]);$this->patch('/technology/monitors/'.$m,['enabled'=>1])->assertRedirect();$this->put('/technology/'.$d,['name'=>'Public domain','status'=>'active','details'=>['hostname'=>'other.com'],'version'=>1])->assertSessionHasErrors('details.hostname');$this->put('/technology/'.$d,['name'=>'Public domain','status'=>'retired','details'=>['hostname'=>'www.example.com'],'version'=>1])->assertRedirect('/technology');$this->assertDatabaseHas('tech_monitors',['id'=>$m,'enabled'=>0]);}
 public function test_sensitive_fields_and_xss():void{[$w,$o]=$this->team();$this->login($o,$w);$this->post('/technology',['kind'=>'repository','name'=>'Bad URL','status'=>'active','details'=>['url'=>'https://user:password@example.com/repo']])->assertSessionHasErrors('details.url');$this->post('/technology',['kind'=>'server','name'=>'Bad field','status'=>'active','details'=>['password'=>'not allowed']])->assertSessionHasErrors('details');$this->asset('documentation','Runbook','active',['description'=>'<script>alert(1)</script>']);$this->get('/technology')->assertOk()->assertDontSee('<script>alert(1)</script>',false)->assertSee('&lt;script&gt;',false);}
}
